@click.command()
@click.option('--flag', is_flag=True, default=False)
def cli(flag):
    click.echo(flag)
for args, dm in [([], {'flag': True}), ([], {'flag': False}), (['--flag'], {'flag': False})]:
    r = runner.invoke(cli, args, default_map=dm)
    print(args, dm, '->', repr(r.output), r.exit_code, r.exception)
