import click
from click.testing import CliRunner
r = CliRunner()

# flag with envvar set to something non-boolean
@click.command()
@click.option("--flag", is_flag=True, envvar="FLAG")
def c(flag): return flag
for v in ["foo", "2", "TRUE", " True"]:
    res = r.invoke(c, [], env={"FLAG": v}, standalone_mode=False)
    print(f"FLAG={v!r} -> {res.return_value!r} exc={res.exception!r}")

# flag with envvar and callback
@click.command()
@click.option("--flag", is_flag=True, envvar="FLAG", callback=lambda ctx, p, v: ("cb", v))
def c2(flag): return flag
res = r.invoke(c2, [], env={"FLAG": "1"}, standalone_mode=False)
print("callback:", repr(res.return_value), repr(res.exception))

# flag with envvar and source
@click.command()
@click.option("--flag", is_flag=True, envvar="FLAG")
@click.pass_context
def c3(ctx, flag):
    return (flag, ctx.get_parameter_source("flag"))
res = r.invoke(c3, [], env={"FLAG": "1"}, standalone_mode=False)
print("source:", repr(res.return_value))
res = r.invoke(c3, [], standalone_mode=False)
print("source unset:", repr(res.return_value))
EOF
